# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs, floor_=3):
    return [v for v in xs if v >= floor_]

# region: intake
def intake(xs, floor_=3):
    return [v for v in xs if v > floor_]

# region: sift
def sift(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
    return out

# region: digest
def digest(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: emit
def emit(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return emit(digest(sift(intake(shape(render(raw))))))

